    /// `DELETE /nodes/{node}/disks/zfs/{name}`
    ///
    /// Destroy a ZFS pool.
    public struct DeleteNodesDisksZfsByName: PVEAPIRequest, Hashable {
        public typealias Response = String
        public static let method: HTTPMethod = .delete
        public static let pathTemplate = "/nodes/{node}/disks/zfs/{name}"
        public static let schemaName = "delete"

        /// The cluster node name.
        ///
        /// Format: `pve-node`.
        public var node: String

        /// The storage identifier.
        ///
        /// Format: `pve-storage-id`.
        public var name: String

        /// Marks associated storage(s) as not available on this node anymore or removes them from the configuration (if configured for this node only).
        ///
        /// Default: `0`.
        public var cleanupConfig: Bool?

        /// Also wipe disks so they can be repurposed afterwards.
        ///
        /// Default: `0`.
        public var cleanupDisks: Bool?

        public init(node: String, name: String) {
            self.node = node
            self.name = name
        }

        public var path: String { PathBuilder.path("nodes", node.parameterValue, "disks", "zfs", name.parameterValue) }

        public var parameters: [(String, String)] {
            var result: [(String, String)] = []
            if let value = cleanupConfig { result.append(("cleanup-config", value.parameterValue)) }
            if let value = cleanupDisks { result.append(("cleanup-disks", value.parameterValue)) }
            return result
        }
    }
